import { SigType, Verifier } from "@ndn/packet";
import { Ed25519Algorithm, ponyfillEd25519 } from "@yoursunny/webcrypto-ed25519";
import { assertSpkiAlgorithm } from "./impl-spki_browser.js";
const subtle = ponyfillEd25519();
class EdAlgo {
    uuid;
    sigType;
    algo;
    oid;
    constructor(uuid, sigType, algo, oid) {
        this.uuid = uuid;
        this.sigType = sigType;
        this.algo = algo;
        this.oid = oid;
    }
    keyUsages = {
        private: ["sign"],
        public: ["verify"],
    };
    async cryptoGenerate({ importPkcs8 }, extractable) {
        let privateKey;
        let publicKey;
        if (importPkcs8) {
            const [pkcs8, spki] = importPkcs8;
            [privateKey, publicKey] = await Promise.all([
                subtle.importKey("pkcs8", pkcs8, this.algo, extractable, this.keyUsages.private),
                subtle.importKey("spki", spki, this.algo, true, this.keyUsages.public),
            ]);
        }
        else {
            ({ privateKey, publicKey } = await subtle.generateKey(this.algo, extractable, [...this.keyUsages.private, ...this.keyUsages.public]));
        }
        const spki = new Uint8Array(await subtle.exportKey("spki", publicKey));
        return {
            privateKey,
            publicKey,
            jwkImportParams: this.algo,
            spki,
            info: {},
        };
    }
    async importSpki(spki, der) {
        assertSpkiAlgorithm(der, this.algo.name, this.oid);
        const key = await subtle.importKey("spki", spki, this.algo, true, this.keyUsages.public);
        return {
            publicKey: key,
            spki,
            info: {},
        };
    }
    makeLLSign({ privateKey }) {
        return async (input) => {
            const raw = await subtle.sign(this.algo, privateKey, input);
            return new Uint8Array(raw);
        };
    }
    makeLLVerify({ publicKey }) {
        return async (input, sig) => {
            const ok = await subtle.verify(this.algo, publicKey, sig, input);
            Verifier.throwOnBadSig(ok);
        };
    }
}
/** Ed25519 signing algorithm. */
export const Ed25519 = new EdAlgo("fa9e8104-39b1-4a8e-828d-8c557d973476", SigType.Ed25519, Ed25519Algorithm, "2B6570");
